PREFIX : <https://semantic-twin-lab.example/TheCabinet.ttl#>
PREFIX x3do: <https://www.web3d.org/specifications/X3dOntology4.1#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX sh: <http://www.w3.org/ns/shacl#>
PREFIX lab: <https://semantic-twin-lab.example/shapes#>
SELECT ?route ?end ?name WHERE {
  ?route a x3do:ROUTE .
  { ?route x3do:fromNode ?name BIND("fromNode" AS ?end) } UNION { ?route x3do:toNode ?name BIND("toNode" AS ?end) }
  FILTER NOT EXISTS { ?node x3do:DEF ?name }
}

